import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlparse
base = 'https://www.gets.govt.nz/ExternalIndex.htm'
source = Path('products/services/nz-gets-data-acceptance-pilot/raw/official-entry.html').read_bytes()
class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.active = None
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.active = [dict(attrs).get('href') or '', []]
    def handle_data(self, data):
        if self.active is not None:
            self.active[1].append(data)
    def handle_endtag(self, tag):
        if tag == 'a' and self.active is not None:
            href, text = self.active
            url = urljoin(base, href)
            label = ' '.join(' '.join(text).split())
            if href and urlparse(url).hostname == 'www.gets.govt.nz' and re.search(r'office|tender|opportunit|rss|feed|rf[xq]|notice', url + ' ' + label, re.I):
                self.links.append({'url': url, 'label': label})
            self.active = None
parser = Links()
parser.feed(source.decode('utf-8', errors='replace'))
record = {'source': base, 'sha256': hashlib.sha256(source).hexdigest(), 'matching_link_count': len(parser.links), 'candidate_links': parser.links[:40], 'coverage': 'Heuristic extraction from a saved entry page. Link availability, current notices, buyer eligibility and market coverage remain unverified.'}
output = Path('products/services/nz-gets-data-acceptance-pilot/director-entry-link-readback.json')
output.write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
